import{_ as d,l as p,o as a,c as s,v as o,p as i,x as t,d as n,i as l,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"双端队列","description":"","frontmatter":{"title":"双端队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deque.md","filePath":"cs/deque.md","lastUpdated":1789023840000}'),h={name:"cs/deque.md"};function u(_,e,m,f,q,T){const r=p("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="双端队列" tabindex="-1">双端队列 <a class="header-anchor" href="#双端队列" aria-label="Permalink to &quot;双端队列&quot;">​</a></h1><div class="epigraph"><p>两端都能进、两端都能出；栈和队列是它在操作集上的两个真子集。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/queue-buffer">上一课</a>钉了 FIFO：尾进头出，并声明双端「主干不提前」。栈是一端 LIFO。本课不重讲环形模运算。缺口是 deque 合同：<code>push_front</code>/<code>push_back</code>/<code>pop_front</code>/<code>pop_back</code> 均摊还或最坏 \\(\\Theta(1)\\)，用来做滑动窗口、两端生长的工作列。表示可以是双向链表，也可以是后课环形数组的两端指针。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只提供队列则无法在队头插入；只提供栈则无法在底端取。算法里「最新的从一端进、过期的从另一端丢」（单调队列）需要两侧。缺口不是新的节点类型，而是<strong>把序列的两端都暴露成 \\(O(1)\\) 端点操作</strong>，中间按下标仍可昂贵。</p><p>空时四端操作无定义或失败；实现不得把「头超过尾」留成未定义环。</p><p><span class="marginnote">STL deque 常用分块数组，使两端增长不必整表复制。本课先钉合同；块列是表示优化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链表表示：双向表的哨兵两侧即两端，四个操作都是改常数条边。数组表示：头尾两个下标，向左增长时 <code>head = (head-1+cap) mod cap</code>——这已是环形缓冲的雏形，下一课专收。</p>',9)),(a(),i(c,null,{default:t(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20PF%5B%22pop_front%22%5D%20--%3E%20SEQ%5B%22%E5%BA%8F%E5%88%97%22%5D%0A%20%20SEQ%20--%3E%20PB%5B%22pop_back%22%5D%0A%20%20PUSHF%5B%22push_front%22%5D%20--%3E%20SEQ%0A%20%20PUSHB%5B%22push_back%22%5D%20--%3E%20SEQ%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>栈 = 只开同一端的 push/pop。队列 = 只开 <code>push_back</code> + <code>pop_front</code>。合同包含关系让测试用例可以共享。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与<a href="/cs/locality-principle">局部性原理</a>：链表 deque 两端操作仍是指针追逐；要扫中间更差。高频滑动窗口若元素连续，数组环形更好。本课允许两种，后课把环形从队列里提出来当独立表示。</p><p>中间插入删除若也要 \\(\\Theta(1)\\)，调用方必须持有节点句柄，那是链表合同，不是下标 deque。混用会把随机访问假装成 \\(O(1)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入优先双端（两端按键），那是堆的变体。也不写无锁 deque。扩容数组在两端同时增长时复制规则更烦，摊还课用单端表扩张即可，不必先在这里证明。</p><p>后课默认：需要两侧端点用 deque。定长高性能缓冲把数组收成环，头尾追逐，下一课只谈那一种布局。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>deque 四端 \\(\\Theta(1)\\)；栈与队列是操作子集。</li><li>链表或环形数组都能表示；局部性偏向数组。</li><li>环形布局与满空区分是下一课。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 对双端队列的接口。</li></ul>',9))])}const S=d(h,[["render",u]]);export{P as __pageData,S as default};
